window.__finlexDocLoaded(10226,{"id":10226,"articles":[{"id":1000935,"no":"Overview","heading":"Scope & Core Objective (Public Summary)","text":"Covers capitalization of interest cost for qualifying constructed assets (ASC 835-20) and imputation of interest / presentation of debt issuance costs (ASC 835-30).","seq":0},{"id":1000936,"no":"ASC 835-20 / 835-30","heading":"Interest Capitalization (Avoidable Interest) & Imputation","text":"• Avoidable Interest (ASC 835-20-30): Capitalize interest on qualifying assets during construction based on weighted-average accumulated expenditures multiplied by specific borrowing rate (optional) and general borrowing weighted-average rate.\n• Temporary Investment Income: Generally NOT netted against capitalized interest (except certain tax-exempt borrowings).\n• Debt Issuance Costs (ASC 835-30-45-1A): Deducted directly from the carrying amount of the debt liability.","seq":1},{"id":1000937,"no":"US GAAP vs. IFRS / CAS","heading":"Key Cross-Framework Differences","text":"• Temporary Investment Income: IAS 23.12 REQUIRES deducting temporary investment income earned on specific borrowings from capitalized borrowing costs; ASC 835-20 generally prohibits netting investment income.","seq":2},{"id":1000938,"no":"Official Access","heading":"Official FASB Codification & Reference Entry","text":"Official Portal (FASB Accounting Standards Codification®): https://asc.fasb.org/\nStatus: in_force (FASB ASC free Basic View available at https://asc.fasb.org/).","seq":3}]});
